# ============================================================================
# CodeX AI Context Exporter
# Commit 1 - Discovery configuration
# ============================================================================


# Unreal content root containing the actual CodeX project architecture.
ROOT_PATH = "/Game/CodeX_Restruct"


# Generated files go under:
#
# <Project>/Saved/CodeX_AI_Context/
#
# Nothing generated by this tool is written into Content/.
OUTPUT_FOLDER_NAME = "CodeX_AI_Context"

# ============================================================================
# Output
# ============================================================================


# Optional external repository used for the generated AI context.
#
# Set to None to use:
#
#   <Project>/Saved/CodeX_AI_Context
#
# Otherwise specifiy local git repo

EXTERNAL_OUTPUT_ROOT = (
    r"D:\GitRepo\FOTCodeX_Project_Context"
)


OUTPUT_FOLDER_NAME = "CodeX_AI_Context"

MIRROR_FOLDER_NAME = "CodeX_Restruct"

# ============================================================================
# Path filtering
# ============================================================================

# Entire subtrees that are not part of the CodeX gameplay/code architecture.
EXCLUDED_PATHS = [
    # Third-party / imported content
    "/Game/CodeX_Restruct/External",

    # Developer-only prototypes / maps
    "/Game/CodeX_Restruct/Developer/Prototypes",
    "/Game/CodeX_Restruct/Developer/TestMaps",

    # Environment / map content
    "/Game/CodeX_Restruct/Game/MapAssets",
    "/Game/CodeX_Restruct/Game/Worlds",

    # ------------------------------------------------------------------------
    # Deprecated Inventory System
    #
    # InventorySystemRefactor is the CURRENT implementation.
    # These sibling folders are the previous implementation.
    # ------------------------------------------------------------------------
    "/Game/CodeX_Restruct/Frameworks/InventorySystemFramework/Inventory",
    "/Game/CodeX_Restruct/Frameworks/InventorySystemFramework/Item",
    "/Game/CodeX_Restruct/Frameworks/InventorySystemFramework/UI",

    "/Game/CodeX_Restruct/Frameworks/EnemyFramework/Shared/VFX/AnimatedBloodSprayDecals"
]

# ============================================================================
# Individual asset filtering
# ============================================================================

# Valid project assets that are intentionally NOT part of the active CodeX
# architecture.
#
# Unlike EXCLUDED_PATHS, these exclusions apply to one exact asset only.
EXCLUDED_ASSETS = {
    # Old grid-based inventory HUD.
    # WBP_PlayerInventoryHUD_manual is the current hand-placed implementation.
    "/Game/CodeX_Restruct/Frameworks/InventorySystemFramework/"
    "InventorySystemRefactor/UI/WBP_PlayerInventoryHUD",

    # Temporary visual/debug Enemy child.
    "/Game/CodeX_Restruct/Frameworks/EnemyFramework/Core/"
    "BP_EnemyBase_CleaverTempChild",

    # Older Boss B animation Blueprint.
    # ABP_BossB is the active implementation.
    "/Game/CodeX_Restruct/Frameworks/BossFramework/Bosses/"
    "Boss_Concubine/ABP/ABP_Boss_B",

    # Experimental targeting implementation; not currently used.
    "/Game/CodeX_Restruct/Frameworks/PlayerFramework/Core/Components/"
    "AC_PlayerTargetingComponent_ComplexScoring",
}

# CodeX convention:
#
# "_dep" anywhere in the asset name means deprecated / old system.
#
# Using a marker instead of a suffix also catches Unreal-generated names such as:
#
# AC_InventoryComponent_dep_C
# Default__AC_InventoryComponent_dep_C

DEPRECATED_NAME_MARKERS = (
    "_dep",
)

# ============================================================================
# Asset classification
# ============================================================================

# These assets contain executable graph logic and will eventually receive
# full graph export:
#
# nodes
# pins
# execution links
# data links
# variables
# functions
# components
# etc.
FULL_GRAPH_CLASS_NAMES = {
    "Blueprint",
    "WidgetBlueprint",
    "AnimBlueprint",
}


# These assets are part of the logical architecture but do not require normal
# K2 Blueprint graph extraction.
STRUCTURAL_CLASS_NAMES = {
    "BehaviorTree",
    "BlackboardData",
    "UserDefinedStruct",
    "UserDefinedEnum",
    "DataTable",
    "InputAction",
    "InputMappingContext",
    "DataAsset",
    "PrimaryDataAsset",
    "StateTree",
}


# Some Data Asset instances use a generated/custom class rather than reporting
# simply "DataAsset" through the Asset Registry.
#
# These prefixes are therefore a SECONDARY safety rule.
#
# Asset class remains our primary classification mechanism.
STRUCTURAL_NAME_PREFIXES = (
    "DA_",
    "DT_",
    "BB_",
    "BT_",
    "IA_",
    "IMC_",
)


# Known content/visual classes that are not part of the exported source-code
# representation.
#
# If an asset class is neither included nor ignored, it goes into REVIEW
# instead of being silently discarded.
